-- Lets a manager delete a payroll period generated by mistake (wrong dates, duplicate run, etc).
-- Restricted to 'draft' periods only -- same rule as every other payroll_entries edit in this
-- app: once locked, a period is a committed record, never destroyed, only corrected via
-- payroll_adjustments. A draft period has no adjustments yet (the UI only allows adding them once
-- status != 'draft'), so there's nothing of that kind to worry about here.
create or replace function public.delete_payroll_period(p_period_id uuid)
returns jsonb
language plpgsql
security definer
set search_path = public
as $$
declare
  v_tenant_id uuid := public.current_tenant_id();
  v_period record;
  v_repayment record;
begin
  if v_tenant_id is null then
    raise exception 'No active tenant for the current user';
  end if;

  if not public.has_permission('can_approve_commission') then
    raise exception 'Not authorized to delete payroll periods';
  end if;

  select * into v_period from public.payroll_periods where id = p_period_id and tenant_id = v_tenant_id;
  if v_period.id is null then
    raise exception 'Payroll period not found';
  end if;

  if v_period.status != 'draft' then
    raise exception 'Only draft periods can be deleted -- a locked or paid period is a committed record';
  end if;

  -- Reverse every cash advance repayment recorded against this period's entries before the
  -- cascade delete below removes the repayment rows -- remaining_balance is a standalone column
  -- on cash_advances, not derived, so it has to be put back explicitly or the advance would look
  -- permanently (and silently) partially repaid.
  for v_repayment in
    select car.* from public.cash_advance_repayments car
    join public.payroll_entries pe on pe.id = car.payroll_entry_id
    where pe.payroll_period_id = p_period_id
  loop
    update public.cash_advances
    set remaining_balance = remaining_balance + v_repayment.amount, status = 'outstanding'
    where id = v_repayment.cash_advance_id;
  end loop;

  -- Release this period's claimed commission back to the unclaimed pool, same shape as before it
  -- was ever generated, so it's available to the next period generated over these dates instead
  -- of being silently lost.
  update public.commission_ledger
  set payroll_period_id = null, status = 'earned'
  where payroll_period_id = p_period_id;

  -- Cascades to payroll_entries, and from there to cash_advance_repayments/payroll_deductions/
  -- payroll_adjustments (0026/0056/0057's own "on delete cascade" FKs).
  delete from public.payroll_periods where id = p_period_id;

  return jsonb_build_object('id', p_period_id, 'deleted', true);
end;
$$;

grant execute on function public.delete_payroll_period(uuid) to authenticated;
